class Solution { public: vector<int> fallingSquares(vector<vector<int>>& positions){vector<array<int,3>> placed;vector<int> answer;int maximum=0;for(auto& position:positions){int left=position[0],right=left+position[1],base=0;for(auto square:placed)if(max(left,square[0])<min(right,square[1]))base=max(base,square[2]);int height=base+position[1];placed.push_back({left,right,height});maximum=max(maximum,height);answer.push_back(maximum);}return answer;} };
